{noformat}bundle exec i18n-tasks mv "user_mailer.admin_deleted_work_notification.{:}.part1" "user_mailer.admin_deleted_work_notification.\1.deleted"{noformat}

To:

{noformat}bundle exec i18n-tasks mv "user_mailer.admin_deleted_work_notification.{:}.part1" "user_mailer.admin_deleted_work_notification.deleted.\1"{noformat}

